            let k = try number()
            c = add(c, try sequence(), k)
        }
        var q = 0
        if peek() == "^" {
            p += 1
            let k = try number()
            let ch = peek()
            if ch != "+" && ch != "-" {
                throw ChemError.message("syntax")
            }
            p += 1
            q = ch == "+" ? k :- k
        }
        if p != chars.count {
            throw ChemError.message("syntax")
        }
        return Formula(c: c, q: q)
